const tableStatus=t=>tableOrders(t.id).length?'occupied':t.status;const statusLabel={free:'Trống',occupied:'Đang dùng',clean:'Cần dọn',locked:'Tạm khóa',waiting:'Chờ nhận',cooking:'Đang làm',ready:'Chờ mang ra',served:'Đã phục vụ',paid:'Đã thanh toán',cancelled:'Đã hủy'};
function orderStatus(o){if(o.cancelled)return'cancelled';if(o.paid)return'paid';if(o.items.every(x=>x.status==='served'))return'served';if(o.items.some(x=>x.status==='ready'))return'ready';if(o.items.some(x=>x.status==='cooking'))return'cooking';return'waiting'}
const badge=(s,label)=>`<span class="badge ${['free','ready','served','done','active'].includes(s)?'green':['cooking','blue'].includes(s)?'blue':['waiting','occupied'].includes(s)?'amber':['failed','cancelled','late'].includes(s)?'red':'grey'}">${esc(label||statusLabel[s]||s)}</span>`,time=t=>new Date(t).toLocaleTimeString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit'}),age=o=>Math.max(0,Math.floor((Date.now()-o.created)/60000)),btn=(label,attrs='',cls='')=>`<button class="button ${cls}" ${attrs}>${label}</button>`;
